BEGIN READ ONLY; SET LOCAL statement_timeout='8s'; SET LOCAL lock_timeout='1s'; SET LOCAL search_path=public,extensions; SELECT jsonb_agg(jsonb_build_object('name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'definition',pg_get_functiondef(p.oid),'body_md5',md5(p.prosrc),'security_definer',p.prosecdef,'settings',p.proconfig,'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text) ORDER BY p.proname) AS metadata FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='net' AND p.proname IN ('http_get','http_post'); ROLLBACK;
